"use strict";
// A constructor function with prototype methods lowers to the object model,
// so `Counter` alone keeps the package native. A class's prototype is laid
// out at compile time, and the member `Meter` adds below exists only at run
// time: that is the mutable object model this package needs (R2.3), and its
// helper package runs inside its island.
const { step } = require("ni-dep");
const { twice } = require("ni-typed");
function Counter() {
  this.count = 0;
}
Counter.prototype.add = function add(n) {
  this.count = step(this.count, twice(n));
};
Counter.prototype.total = function total() {
  return this.count;
};
class Meter {
  constructor() {
    this.ticks = 0;
  }
  tick() {
    this.ticks += 1;
  }
}
Meter.prototype.reset = function reset() {
  this.ticks = 0;
};
exports.Counter = Counter;
exports.Meter = Meter;
